<?php namespace App\Actions; use App\Models\FoodItem; use App\Models\Order; use App\Models\OrderItem; use App\Models\User; use Illuminate\Support\Facades\DB; use InvalidArgumentException; class CreateOrderAction { public function execute(User $student, int $stallId, string $pickupTime, array $items): Order { return DB::transaction(function () use ($student, $stallId, $pickupTime, $items) { $total = 0; $preparedItems = []; foreach ($items as $item) { $food = FoodItem::findOrFail($item['food_item_id']); if ($food->stall_id !== $stallId || !$food->availability) { throw new InvalidArgumentException('Invalid or unavailable food item.'); } $qty = (int) $item['quantity']; $total += $food->price * $qty; $preparedItems[] = ['food' => $food, 'quantity' => $qty]; } $order = Order::create(['user_id' => $student->id, 'stall_id' => $stallId, 'pickup_time' => strip_tags($pickupTime), 'total_amount' => $total, 'status' => 'Pending', 'payment_status' => 'Unpaid']); foreach ($preparedItems as $p) { OrderItem::create(['order_id' => $order->id, 'food_item_id' => $p['food']->id, 'quantity' => $p['quantity'], 'unit_price' => $p['food']->price]); } return $order->load('orderItems.foodItem'); }); } }